```java
@Service
public class AiService {
    @Retryable(
        retryFor = {HttpClientErrorException.TooManyRequests.class},
        maxAttempts = 4,
        backoff = @Backoff(delay = 1000, multiplier = 2.0, maxDelay = 16000)
    )
    public String call(String prompt) {
        return chatClient.prompt().user(prompt).call().content();
    }

    @Recover
    public String fallback(HttpClientErrorException e, String prompt) {
        log.error("Rate limit exceeded after retries", e);
        throw new ServiceUnavailableException("LLM API unavailable");
    }
}
```

